//Code your testbench here
//or browse Examples`timescale 1ns/1ps
`include "uvm_macros.svh"
import uvm_pkg::*;

//RAL package generated by PeakRDL; must be included before any use.
`include "aligner_apb_registerfile_model.sv"
`include "aligner_reg_coverage.sv" //modelo de registros con clases para cobertura
import aligner_apb_registerfile_model::*;

//Interfaces
`include "apb_if.sv"
`include "md_if.sv"

//Seq Items
`include "seq_item_apb.sv"
`include "md_seq_item.sv"

//APB
`include "apb_monitor.sv"
`include "apb_driver.sv"
`include "adapter.sv"
`include "apb_agent.sv"
`include "apb_sequence.sv"

//MD
`include "md_rx_driver.sv"
`include "md_tx_driver.sv"
`include "md_monitor.sv"
`include "md_agent.sv"
`include "md_rx_sequences.sv"

//Scoreboard, cobertura, env, test
`include "aligner_scoreboard.sv"
`include "aligner_md_coverage.sv" //collector de cobertura funcional del canal MD
`include "aligner_env.sv"
`include "aligner_test.sv"

//Assertions (modulo SVA que se conecta directo a las senales del DUT)
`include "aligner_assertions.sv"

//DUT
`include "design.v"

//modulo top del testbench: instancia el DUT, las interfaces y arranca el test
module aligner_tb_top;

    localparam int ALGN_DATA_WIDTH = 32; //ancho de datos del alineador
    localparam int FIFO_DEPTH      = 8;  //profundidad de las fifos

    logic clk;     //reloj global
    logic reset_n; //reset activo en bajo

    //generar clok
    initial clk = 1'b0;
    always #5 clk = ~clk; //reloj de periodo 10ns

    //reset bajo
    initial begin
        $fsdbDumpfile("dump.fsdb");
        $fsdbDumpvars(0, aligner_tb_top);//para ver formas de onda
        reset_n = 1'b0;
        repeat (5) @(posedge clk); //mantiene el reset unos ciclos
        @(negedge clk);
        reset_n = 1'b1; //libera el reset
        `uvm_info("TB_TOP", "Reset liberado", UVM_NONE)
    end


    //interfaz APB conectada al reloj y reset
    apb_if #(
        .ADDR_WIDTH(16),
        .DATA_WIDTH(32)
    ) apb_bus (
        .PCLK   (clk),
        .PRESETn(reset_n)
    );

    //interfaz MD conectada al reloj y reset
    md_if #(
        .DATA_WIDTH(ALGN_DATA_WIDTH)
    ) md_bus (
        .clk    (clk),
        .reset_n(reset_n)
    );

    //dut
    cfs_aligner #(
        .ALGN_DATA_WIDTH(ALGN_DATA_WIDTH),
        .FIFO_DEPTH     (FIFO_DEPTH)
    ) dut (
        .clk        (clk),
        .reset_n    (reset_n),

        // APB
        .paddr      (apb_bus.PADDR),
        .pwrite     (apb_bus.PWRITE),
        .psel       (apb_bus.PSEL),
        .penable    (apb_bus.PENABLE),
        .pwdata     (apb_bus.PWDATA),
        .pready     (apb_bus.PREADY),
        .prdata     (apb_bus.PRDATA),
        .pslverr    (apb_bus.PSLVERR),

        // MD RX
        .md_rx_valid (md_bus.md_rx_valid),
        .md_rx_data  (md_bus.md_rx_data),
        .md_rx_offset(md_bus.md_rx_offset),
        .md_rx_size  (md_bus.md_rx_size),
        .md_rx_ready (md_bus.md_rx_ready),
        .md_rx_err   (md_bus.md_rx_err),

        // MD TX
        .md_tx_valid (md_bus.md_tx_valid),
        .md_tx_data  (md_bus.md_tx_data),
        .md_tx_offset(md_bus.md_tx_offset),
        .md_tx_size  (md_bus.md_tx_size),
        .md_tx_ready (md_bus.md_tx_ready),
        .md_tx_err   (md_bus.md_tx_err),

        // IRQ
        .irq        ()
    );

    //modulo de assertions, pegado directo a las senales del DUT
    aligner_assertions #(
        .ADDR_WIDTH(16),
        .DATA_WIDTH(ALGN_DATA_WIDTH)
    ) assertions (
        .clk         (clk),
        .reset_n     (reset_n),

        // APB
        .psel        (apb_bus.PSEL),
        .penable     (apb_bus.PENABLE),
        .pwrite      (apb_bus.PWRITE),
        .pready      (apb_bus.PREADY),
        .pslverr     (apb_bus.PSLVERR),
        .paddr       (apb_bus.PADDR),
        .pwdata      (apb_bus.PWDATA),

        // MD RX
        .md_rx_valid (md_bus.md_rx_valid),
        .md_rx_ready (md_bus.md_rx_ready),
        .md_rx_err   (md_bus.md_rx_err),
        .md_rx_size  (md_bus.md_rx_size),
        .md_rx_offset(md_bus.md_rx_offset),

        // MD TX
        .md_tx_valid (md_bus.md_tx_valid),
        .md_tx_ready (md_bus.md_tx_ready),
        .md_tx_err   (md_bus.md_tx_err),
        .md_tx_size  (md_bus.md_tx_size),
        .md_tx_offset(md_bus.md_tx_offset)
    );


    initial begin
        //se publican las interfaces virtuales para que los agentes las obtengan
        // APB
        uvm_config_db #(virtual apb_if)::set(null, "uvm_test_top.*", "vif", apb_bus);
        // MD
        uvm_config_db #(virtual md_if)::set(null, "uvm_test_top.*", "md_vif", md_bus);
        //Arrancar el test
        run_test("aligner_test");
    end

    //watchdog: si la simulacion se pasa de tiempo, se corta con error
    initial begin
        #1_000_000;
        `uvm_fatal("TB_TOP", "Timeout de simulación alcanzado")
    end


endmodule
